import { describe, expect, it } from "vitest";
import { existsSync, readdirSync, readFileSync } from "node:fs";

// The phone report is generated by `scripts/acceptance-phone.ts` on real
// devices. This test is the shape gate: a report that lost its screenshots, or
// that carries a raw device id, must fail before it reaches the site.
const REPORT = new URL("../../../../docs/acceptance/phone-0.10.0/report.json", import.meta.url);

interface Case {
  id: string;
  title: string;
  status: "pass" | "fail" | "skip";
  detail: string;
  screenshots: string[];
  kind?: "screen" | "log";
  device?: string;
}

function load() {
  return JSON.parse(readFileSync(REPORT, "utf8")) as {
    product: string;
    version: string;
    date: string;
    commit: string;
    devices: { tag: string; model: string; resolution: string }[];
    cases: Case[];
    summary: { passed: number; failed: number; skipped: number };
    rerun: string[];
    issues: string[];
  };
}

describe("phone acceptance report", () => {
  it("is the 0.10.0 phone report", () => {
    expect(existsSync(REPORT)).toBe(true);
    const report = load();
    expect(report.product).toBe("phone");
    expect(report.version).toBe("0.10.0");
    expect(report.date).toMatch(/^\d{4}-\d{2}-\d{2}$/);
    expect(report.commit).toMatch(/^[0-9a-f]{7,40}$/);
  });

  it("covers the 21 commands and the approval and hold flows", () => {
    const ids = load().cases.map((c) => c.id);

    // One case per CLI command, named `cmd-<command>`.
    const commands = ids.filter((id) => id.startsWith("cmd-"));
    expect(commands.length).toBeGreaterThanOrEqual(21);
    for (const id of ["cmd-launch", "cmd-observe", "cmd-tap", "cmd-handoff"]) {
      expect(ids).toContain(id);
    }
    for (const id of ["approval-pending", "approval-allow", "hold-blocks-agent", "resume-releases", "mcp"]) {
      expect(ids).toContain(id);
    }
  });

  it("gives every non-skip case something to show", () => {
    const report = load();
    for (const c of report.cases) {
      if (c.status === "skip") continue;
      if (c.kind === "log") {
        expect(c.detail.trim().length, `${c.id} has no result text`).toBeGreaterThan(0);
        continue;
      }
      expect(c.screenshots.length, `${c.id} (${c.title}) has no screenshot`).toBeGreaterThan(0);
    }
    const pictures = report.cases.reduce((n, c) => n + c.screenshots.length, 0);
    expect(pictures).toBeGreaterThanOrEqual(2);
  });

  it("names the device on every case and never the serial", () => {
    const report = load();
    const text = readFileSync(REPORT, "utf8");
    // A serial-shaped token: an 8+ character device id, not the 8-hex tag.
    expect(text).not.toMatch(/\b(?:FMR|9CN|MLR)\d{6,}/);
    const tags = [...report.devices.map((d) => d.tag), "host"];
    for (const c of report.cases) {
      if (c.device) expect(tags).toContain(c.device);
    }
  });

  it("counts what it lists", () => {
    const { cases, summary } = load();
    expect(summary.passed).toBe(cases.filter((c) => c.status === "pass").length);
    expect(summary.failed).toBe(cases.filter((c) => c.status === "fail").length);
    expect(summary.skipped).toBe(cases.filter((c) => c.status === "skip").length);
  });

  // A screenshot is evidence of what this run saw. A picture left behind by an
  // earlier run — the same path, a different screen — makes a passing case look
  // proven when nothing was captured, so every picture the report names must be
  // from this run's own screenshots directory.
  it("publishes no picture that this run did not take", () => {
    const report = load();
    const dir = new URL("../../../../docs/acceptance/phone-0.10.0/screenshots/", import.meta.url);
    const onDisk = new Set(readdirSync(dir));

    for (const c of report.cases) {
      for (const shot of c.screenshots) {
        expect(onDisk.has(shot), `${c.id} names ${shot}, which is not on disk`).toBe(true);
      }
    }

    // And the other direction: a picture in the folder that no case names is
    // stale evidence from a previous run sitting in the published directory.
    const named = new Set(report.cases.flatMap((c) => c.screenshots));
    const orphans = [...onDisk].filter((f) => f.endsWith(".jpg") && !named.has(f));
    expect(orphans, `screenshots left over from an earlier run: ${orphans.join(", ")}`).toEqual([]);
  });
});
